<!--vbase-->
<template>
  <q-markup-table class='full-width sticky-header table-height line-item-table-design' v-if="tableRows.length > 0">
    <thead>
      <tr class="highlighted-back">
        <th v-for='column in tableColumns' v-bind:key='column.name' class='text-left'>
          <div style='width: 100%' class='text-left'>
            {{ column.label }}
            <q-icon v-if="column.icon" :name="'img:/images/charges/' + column.icon" size="xs"
              class="icon-grey-svg q-ml-md" />

            <q-icon v-if="approvalNeededColumns.has(column.name)" class="cursor-pointer  q-ml-md" name="menu" size="xs">
              <q-menu fit auto-close anchor="bottom middle" self="top middle">
                <div class="row no-wrap q-pa-sm q-pb-md">
                  <div class="col-sm-12 col-md-12 col-lg-12">
                    <q-btn round color="positive" icon="done" size="xs" class="q-mr-sm"
                      @click="approveOrRecject(column.name, approvalInfoStatus.approved, column.originalName)">
                      <q-tooltip> {{ $t('accept_all') }} </q-tooltip>
                    </q-btn>
                    <q-btn round color="red-5" icon="close" size="xs" class="q-mr-sm"
                      @click="approveOrRecject(column.name, approvalInfoStatus.rejected, column.originalName)">
                      <q-tooltip> {{ $t('reject_all') }} </q-tooltip>
                    </q-btn>
                    <q-btn round color="grey-5" icon="delete" size="xs"
                      @click="approveOrRecject(column.name, approvalInfoStatus.pending, column.originalName)">
                      <q-tooltip> {{ $t('remove') }} </q-tooltip>
                    </q-btn>
                  </div>
                </div>
              </q-menu>
            </q-icon>

          </div>
        </th>
      </tr>
    </thead>
    <tbody>
      <template v-for='(line, index1) in tableRows' :key='index1'>
        <tr>
          <template v-for='(column, index2) in tableColumns' :key='index2'>
            <td v-if="line[column.name]" :class="line[column.name].class">
              <template v-if="!column.label">
                <q-icon name="warning" color="warning" v-if="line[column.name].value" />
              </template>
              <template v-else>
                {{ column.numeric ? roundOff(line[column.name].value, 4) : line[column.name].value }}
                <span v-if="line[column.name].amount" class="text-italic text-bold"> 
                  ({{ column.numeric ? roundOff(line[column.name].amount, 4) : line[column.name].amount }})</span>
              </template>

              <q-icon v-if="line[column.name].class.startsWith('no-left-border')" class="float-right cursor-pointer"
                name="menu" size="xs">
                <q-menu fit auto-close anchor="bottom middle" self="top middle">
                  <div class="row no-wrap q-pa-sm q-pb-md">
                    <div class="col-sm-12 col-md-12 col-lg-12">
                      <q-btn round color="positive" icon="done" size="xs" class="q-mr-sm"
                        @click="proceedWithApprovalWrapper(line, column.name, column.originalName)" />
                      <q-btn round color="red-5" icon="close" size="xs" class="q-mr-sm"
                        @click="proceedWithRejectionWrapper(line, column.name, column.originalName)" />
                      <q-btn round color="grey-5" icon="delete" size="xs" @click="restStatusWrapper(line, column.name, column.originalName)" />
                    </div>
                  </div>
                </q-menu>
              </q-icon>
              </td>
              <td v-else>
                
              </td>
          </template>
        </tr>
      </template>
    </tbody>
  </q-markup-table>
  <q-markup-table class='full-width' v-else>
    <thead>
      <tr class='highlighted-back'>
        <th>{{ $t('NO_PO_MATCHING_FOUND') }}</th>
      </tr>
    </thead>
  </q-markup-table>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import sessionHelper from 'src/utils/sessionHelper';
import { notify } from 'src/components/notifications/notify';
import { approvalInfoStatus, charges_table_extraction } from 'src/constants';
import { useDocumentStore, usePoMatchStore, useMasterDataLookupStore, useSettingStore, useAuthTokenStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperUtil, sessionHelper, dateUtils],
  props: {
    columnLblPrefix: {
      type: String,
      default: ''
    }
  },
  data() {
    return {
      tableColumns: ref([] as any),
      tableRows: ref([] as any),
      colorOrange: 'orange',
      colorSucess: 'sucess',
      colorError: 'error',
      approvalInfoStatus: approvalInfoStatus,
    };
  },
  mounted: function () {
    this.init();
  },
  methods: {
    async init() {
      this.prepareLineMapping();
      if (this.user_settings[charges_table_extraction]) {
        await this.prepareCostingElementDictionary();
      }
      await this.prepareChargesFields();
      this.prepareTableData();
    },
    prepareTableData() {
      if (!this.record.po_items) {
        return;
      }

      this.buildPoLinesObj(this.record.po_items);
      this.prepareLinedictionary();

      this.prepareTableColumns();
      this.prepareTableRow();
    },
    prepareTableColumns() {
      // Base columns that are always shown.
      // `numeric` decides whether a cell is pushed through roundOff() when
      // rendered. Identifier/text columns MUST stay false: item numbers such as
      // '9338.81235' or '0012.3450' are master-data strings, not amounts, and
      // rounding them corrupts the value shown to the user (BOL-471).
      this.tableColumns = [
        {
          name: 'icons_area',
          field: 'icons_area',
          align: 'left',
          label: '',
          sortable: false,
          originalName: 'icons_area',
          numeric: false,
        },
        {
          name: 'position_number',
          field: 'position_number',
          align: 'left',
          label: this.$t('position_number'),
          sortable: true,
          originalName: 'position_number',
          numeric: false,
        },
        {
          name: 'item_number',
          field: 'item_number',
          align: 'left',
          label: this.$t('item_number'),
          sortable: true,
          originalName: 'item_number',
          numeric: false,
        },
        {
          name: 'description',
          field: 'description',
          align: 'left',
          label: this.$t('description'),
          sortable: true,
          originalName: 'description',
          numeric: false,
        },
        {
          name: 'unit',
          field: 'unit',
          align: 'left',
          label: this.$t('unit'),
          sortable: true,
          originalName: 'unit',
          numeric: false,
        },
      ];

      // Collect all unique field keys from approval_comparison_data
      const comparisonFields = this.collectComparisonFields();

      // Add dynamic columns based on approval_comparison_data fields
      for (const fieldName of comparisonFields) {
        const poColumnName = 'po_' + fieldName;
        const invoiceColumnName = 'invoice_' + fieldName;

        // If this column exists in base tableColumns, remove it first
        const existingIndex = this.tableColumns.findIndex((col: { name: string }) => col.name.toLowerCase() === fieldName);
        if (existingIndex !== -1) {
          this.tableColumns.splice(existingIndex, 1);
        }

        // Create PO column
        // approval_comparison_data pairs are compared amounts/quantities/dates,
        // so they keep the 4-decimal rounding.
        this.tableColumns.push({
          name: poColumnName,
          field: poColumnName,
          align: 'left',
          label: 'PO: ' + this.$t(fieldName),
          sortable: true,
          originalName: fieldName,
          numeric: true,
        });

        // Create Invoice/Line column
        this.tableColumns.push({
          name: invoiceColumnName,
          field: invoiceColumnName,
          align: 'left',
          label: (this.columnLblPrefix ? this.columnLblPrefix + ': ' : '') + this.$t(fieldName),
          sortable: true,
          originalName: fieldName,
          numeric: true,
        });
      }
    },

    collectComparisonFields(): string[] {
      const fieldsSet = new Set<string>();

      if (!this.record.po_multi_matched || this.record.po_multi_matched.length === 0) {
        return [];
      }

      for (const data of this.record.po_multi_matched) {
        if (data.hasOwnProperty('sub_lines')) {
          // Handle multi PO to one line case
          for (const subline of data.sub_lines) {
            this.extractComparisonFields(subline, fieldsSet);
          }
        } else {
          this.extractComparisonFields(data, fieldsSet);
        }
      }

      return Array.from(fieldsSet);
    },

    extractComparisonFields(data: any, fieldsSet: Set<string>) {
      if (data.approval_comparison_data) {
        for (const key of Object.keys(data.approval_comparison_data)) {
          // Extract field name by removing _actual or _expected suffix
          // Skip tolerance fields
          if (key.endsWith('_actual')) {
            const fieldName = key.replace('_actual', '');
            // Check if corresponding _expected exists
            if (data.approval_comparison_data[fieldName + '_expected'] !== undefined) {
              fieldsSet.add(fieldName);
            }
          }
        }
      }
    },

    prepareTableRow() {
      this.tableRows = [];
      if (!this.record.po_multi_matched || this.record.po_multi_matched.length == 0) {
        return;
      }

      for (let [index, data] of this.record.po_multi_matched.entries()) {

        if (data.hasOwnProperty('sub_lines')) {
          // multi po and one line
          this.multiPoToOneLine(data);

        } else if (data.hasOwnProperty('table_lines')) {
          // one po and multi line
          this.onePoToOneLine(data);

        } else {
          this.onePoToOneLine(data);
        }
      }
    },
    multiPoToOneLine(data: any) {

      for (const subline of data.sub_lines) {
        this.onePoToOneLine(subline);
      }
    },
    onePoToOneLine(data: any) {
      const params: any = {};

      // Build params from approval_comparison_data dynamically
      if (data.approval_comparison_data) {
        const processedFields = new Set<string>();

        for (const key of Object.keys(data.approval_comparison_data)) {
          // Extract field name by removing _actual suffix
          if (key.endsWith('_actual')) {
            const fieldName = key.replace('_actual', '');

            // Skip if already processed or no corresponding _expected
            if (processedFields.has(fieldName)) continue;
            if (data.approval_comparison_data[fieldName + '_expected'] === undefined) continue;

            processedFields.add(fieldName);

            const poKey = 'po_' + fieldName;
            const invoiceKey = 'invoice_' + fieldName;

            let poValue = data.approval_comparison_data[fieldName + '_expected'];
            let invoiceValue = data.approval_comparison_data[fieldName + '_actual'];

            // Store original values before formatting (for dates)
            const originalPoValue = poValue;
            const originalInvoiceValue = invoiceValue;

            // Format dates if the field name contains 'date'
            if (fieldName.includes('date')) {
              poValue = this.formatDateAccordingToPreference(poValue, true);
              invoiceValue = this.formatDateAccordingToPreference(invoiceValue, true);
            }

            params[poKey] = poValue !== undefined && poValue !== null ? poValue : '';
            params[invoiceKey] = invoiceValue !== undefined && invoiceValue !== null ? invoiceValue : '';
            params[poKey + '_original'] = originalPoValue !== undefined && originalPoValue !== null ? originalPoValue : '';
            params[invoiceKey + '_original'] = originalInvoiceValue !== undefined && originalInvoiceValue !== null ? originalInvoiceValue : '';
          }
        }
      }

      this.createNewTableRow(data, params);
    },
    createNewTableRow(data: any, params: any) {
      let showIcon = false;

      const row: any = {
        'icons_area': { 'value': showIcon, 'class': '' },
        'po_line_id': { 'value': data.po_line_id, 'class': '' },
        'position_number': { 'value': this.PODataObj[data.po_line_id].line_number, 'class': '' },
        'item_number': { 'value': this.PODataObj[data.po_line_id].item_id, 'class': '' },
        'description': { 'value': this.PODataObj[data.po_line_id].description, 'class': '' },
        'unit': { 'value': this.PODataObj[data.po_line_id].unit_code, 'class': '' },
      };

      // Add dynamic fields from approval_comparison_data to the row
      if (data.approval_comparison_data) {
        const processedFields = new Set<string>();

        for (const key of Object.keys(data.approval_comparison_data)) {
          // Extract field name by removing _actual suffix
          if (key.endsWith('_actual')) {
            const fieldName = key.replace('_actual', '');

            // Skip if already processed or no corresponding _expected
            if (processedFields.has(fieldName)) continue;
            if (data.approval_comparison_data[fieldName + '_expected'] === undefined) continue;

            processedFields.add(fieldName);

            const poKey = 'po_' + fieldName;
            const invoiceKey = 'invoice_' + fieldName;

            // Get style class based on approval_info or value mismatch
            let applyClass = this.getStyleClassForNormalColumns(data, fieldName);

            // Don't show the orange (approval-needed) border when either the PO or line value is empty
            const poFieldEmpty = params[poKey] === undefined || params[poKey] === null || params[poKey] === '';
            const invoiceFieldEmpty = params[invoiceKey] === undefined || params[invoiceKey] === null || params[invoiceKey] === '';
            if (applyClass === this.colorOrange && (poFieldEmpty || invoiceFieldEmpty)) {
              applyClass = '';
            }

            // Update showIcon if this field needs approval
            if (applyClass == this.colorOrange) {
              row['icons_area'].value = true;
            }

            // Add to approval needed columns
            if (applyClass) {
              this.approvalNeededColumns.add(invoiceKey);
            }

            // Add PO column to row
            row[poKey] = {
              'value': params[poKey] !== undefined ? params[poKey] : '',
              'original_value': params[poKey + '_original'] !== undefined ? params[poKey + '_original'] : '',
              'actual_name': fieldName,
              'class': applyClass ? 'no-right-border-' + applyClass : ''
            };

            // Add Invoice column to row with po_pair_name for calculations
            row[invoiceKey] = {
              'value': params[invoiceKey] !== undefined ? params[invoiceKey] : '',
              'original_value': params[invoiceKey + '_original'] !== undefined ? params[invoiceKey + '_original'] : '',
              'actual_name': fieldName,
              'class': applyClass ? 'no-left-border-' + applyClass : '',
              'po_pair_name': poKey
            };
          }
        }
      }

      if (data.additional_charges && data.additional_charges.length >= 0) {
        this.additionalCharges(data.additional_charges, row);
      }

      this.tableRows.push(row);
    },
    additionalCharges(additionalCharges: any, tableRow: any) {
      for (const charge of additionalCharges) {

        if (!charge.costing_element) {
          continue;
        }
        this.addNewColumnIfNotExist(charge, tableRow);
      }
    },
    addNewColumnIfNotExist(charge: any, tableRow: any) {
      let columnFound = false;
      for (let column of this.tableColumns) {
        if (column.field == charge.costing_element) {

          columnFound = true;
          break;
        }
      }

      const poColumnName = 'po_' + charge.costing_element;
      const invoiceColumnName = 'invoice_' + charge.costing_element;

      if (!columnFound) {

        const costingElement = this.costingElementDictionary[charge.costing_element];

        const label = costingElement ? costingElement.label : charge.costing_element

        // Charge columns hold rates/prices and their amounts -> rounded.
        this.tableColumns.push({
          name: poColumnName,
          field: charge.costing_element,
          align: 'left',
          label: 'PO: ' + label,
          icon: costingElement ? costingElement.icon : '',
          sortable: true,
          originalName: this.getChargesNameByCostingElement(charge.costing_element),
          numeric: true,
        });

        this.tableColumns.push({
          name: invoiceColumnName,
          field: charge.costing_element,
          align: 'left',
          label: (this.columnLblPrefix ? this.columnLblPrefix + ': ' : '') + label,
          sortable: true,
          originalName: this.getChargesNameByCostingElement(charge.costing_element),
          numeric: true,
        });
      }

      let styleClass = this.getStyleClassForChargesColumns(charge);

      let poValue = '';
      let poAmount = charge.po_charge_amount;
      let lineValue = '';
      let lineAmount = charge.amount;

      if (charge.is_tax) {
        poValue = charge.expected_charge_rate;
        lineValue = charge.charge_rate;
      } else {
        poValue = charge.expected_unit_price;
        lineValue = charge.unit_price;
      }

      // Don't show the orange (approval-needed) border when either the PO or line value is empty
      const poValueEmpty = poValue === undefined || poValue === null || poValue === '';
      const lineValueEmpty = lineValue === undefined || lineValue === null || lineValue === '';
      if (styleClass == this.colorOrange && (poValueEmpty || lineValueEmpty)) {
        styleClass = '';
      }

      if (styleClass == this.colorOrange) {
        tableRow.icons_area.value = true;
      }

      if (styleClass) {
        this.approvalNeededColumns.add(invoiceColumnName);
      }

      // add object in the row
      tableRow[poColumnName] = { 'value': poValue, 'amount': poAmount, 'class': styleClass ? 'no-right-border-' + styleClass : '' };

      // adding 'po_pair_name' and 'isChargeField' attribite it will be used later on for calculations
      tableRow[invoiceColumnName] = { 'value': lineValue, 'amount': lineAmount, 'charge_code': charge.costing_element, 'class': styleClass ? 'no-left-border-' + styleClass : '', 'po_pair_name': poColumnName, 'is_charge': true };
    },
    getStyleClassForNormalColumns(data: any, approvalKey: string) {
      let styleClass = '';

      if (data.approval_info && data.approval_info[approvalKey] && data.approval_info[approvalKey].approval_required) {
        styleClass = this.colorOrange;
        const approval_status = data.approval_info[approvalKey].approval_status;
        if (approval_status) {
          styleClass = approval_status == approvalInfoStatus.approved ? this.colorSucess : this.colorError;
        }
      }
      return styleClass;
    },
    getStyleClassForChargesColumns(charge: any) {

      let styleClass = ''
      if (charge.approval_info && charge.approval_info.approval_required) {

        styleClass = this.colorOrange;
        const approval_status = charge.approval_info.approval_status;
        if (approval_status) {
          styleClass = approval_status == approvalInfoStatus.approved ? this.colorSucess : this.colorError;
        }
      }
      return styleClass;
    },

    approveOrRecject(columnName: string, status: string, originalName: string) {
      // check for user permistion
      if (!this.checkTableApprovalpermission(originalName)) {
        notify.error(this.$t('NOT_AUTHORIZED_TO_APPROVE'));
        return;
      }

      for (let row of this.tableRows) {
        for (let [index, column] of Object.entries(row)) {
          if (columnName == index && (column as any).class.startsWith('no-left-border')) {

            if (this.approvalInfoStatus.approved == status) {
              this.proceedWithApproval(row, columnName);
            } else if (this.approvalInfoStatus.rejected == status) {
              this.proceedWithRejection(row, columnName);
            } else {
              this.restStatus(row, columnName);
            }
          }
        }
      }
    },
    proceedWithApprovalWrapper(rowInfo: any, columnName: string, originalName: string) {
      // check for user permistion
      if (!this.checkTableApprovalpermission(originalName)) {
        notify.error(this.$t('NOT_AUTHORIZED_TO_APPROVE'));
        return;
      }
      this.proceedWithApproval(rowInfo, columnName);
    },
    proceedWithApproval(rowInfo: any, columnName: string) {

      this.handleApprovalInfo(approvalInfoStatus.approved, columnName, rowInfo);
      const poPairColumnName = rowInfo[columnName].po_pair_name;
      rowInfo[columnName].class = 'no-left-border-sucess';
      rowInfo[poPairColumnName].class = 'no-right-border-sucess';
      this.handleRowApprovalStatus(rowInfo);

    },

    handleRowApprovalStatus(rowInfo: any) {
      let approvalNeeded = false;
      for (const [key, item] of Object.entries(rowInfo)) {
        if ((item as any).class && (item as any).class.endsWith(this.colorOrange)) {
          approvalNeeded = true;
          break;
        }
      }
      // Update icons_area based on whether any field needs approval
      rowInfo.icons_area.value = approvalNeeded;
    },
    proceedWithRejectionWrapper(rowInfo: any, columnName: string, originalName: string) {
      // check for user permistion
      if (!this.checkTableApprovalpermission(originalName)) {
        notify.error(this.$t('NOT_AUTHORIZED_TO_APPROVE'));
        return;
      }
      this.proceedWithRejection(rowInfo, columnName);
    },
    proceedWithRejection(rowInfo: any, columnName: string) {

      this.handleApprovalInfo(approvalInfoStatus.rejected, columnName, rowInfo);
      const poPairColumnName = rowInfo[columnName].po_pair_name;
      rowInfo[columnName].class = 'no-left-border-error';
      rowInfo[poPairColumnName].class = 'no-right-border-error';
      this.handleRowApprovalStatus(rowInfo);
    },
    restStatusWrapper(rowInfo: any, columnName: string, originalName: string) {
      // check for user permistion
      if (!this.checkTableApprovalpermission(originalName)) {
        notify.error(this.$t('NOT_AUTHORIZED_TO_APPROVE'));
        return;
      }
      this.restStatus(rowInfo, columnName);
    },
    restStatus(rowInfo: any, columnName: string) {

      this.handleApprovalInfo(approvalInfoStatus.pending, columnName, rowInfo);
      const poPairColumnName = rowInfo[columnName].po_pair_name;
      rowInfo[columnName].class = 'no-left-border-orange';
      rowInfo[poPairColumnName].class = 'no-right-border-orange';
      this.handleRowApprovalStatus(rowInfo);
    },
    handleApprovalInfo(status: string, columnName: string, rowInfo: any) {

      const poLineId = rowInfo.po_line_id.value;
      const poPairColumnName = rowInfo[columnName].po_pair_name;
      const fieldName = rowInfo[columnName].actual_name;

      // Use original_value for date fields to avoid saving formatted dates
      let lineFieldValue = rowInfo[columnName].value;
      let poFieldValue = rowInfo[poPairColumnName].value;

      if (fieldName && fieldName.toLowerCase().includes('date')) {
        lineFieldValue = rowInfo[columnName].original_value || lineFieldValue;
        poFieldValue = rowInfo[poPairColumnName].original_value || poFieldValue;
      }

      const approvalInfoParam = {
        'status': status,
        'currentUserId': this.getLoggedinUserId(),
        'currentDateTime': Date.now(),
        'lineFieldValue': isNaN(lineFieldValue) ? lineFieldValue : Number(lineFieldValue),
        'poFieldValue': isNaN(poFieldValue) ? poFieldValue : Number(poFieldValue),
      }

      mainLoop:
      for (let [index, record] of this.record.po_multi_matched.entries()) {

        if (record.hasOwnProperty('po_line_id')) {
          if (record.po_line_id == poLineId) {

            this.updatePORow(record, rowInfo[columnName], approvalInfoParam, rowInfo[columnName].actual_name);
            break mainLoop;
          }

        } else if (record.hasOwnProperty('sub_lines')) {
          for (let [sub_index, sub_line] of record.sub_lines.entries()) {
            if (sub_line.po_line_id == poLineId) {

              this.updatePORow(sub_line, rowInfo[columnName], approvalInfoParam, rowInfo[columnName].actual_name);
              break mainLoop;
            }
          }
        }
      }
    },
    updatePORow(record: any, columnInfo: any, approvalInfoParam: any, attributeName: string) {

      if (columnInfo.is_charge) {
        for (let charge of record.additional_charges) {
          if (charge.costing_element == columnInfo.charge_code) {
            let approvalType = 'unit_price';
            if (charge.is_tax) {
              approvalType = 'charge_rate';
            }
            charge['approval_info'] = this.getApprovalInfoDetails(approvalInfoParam, approvalType, true, attributeName, charge['approval_info']);
            return;
          }
        }
      } else {
        // Initialize approval_info if it doesn't exist
        if (!record.approval_info) {
          record.approval_info = {};
        }

        // Get existing approval info or empty object (attributeName is already lowercase)
        const existingApprovalInfo = record.approval_info[attributeName] || {};

        record.approval_info[attributeName] = this.getApprovalInfoDetails(approvalInfoParam, 'amount', false, attributeName, existingApprovalInfo);
      }
    },
    getApprovalInfoDetails(approvalInfoParam: any, approvedPropertyName: string, isCharges: boolean, attributeName: string, approvalInfo: any): any {
      // Ensure approvalInfo is an object
      const safeApprovalInfo = approvalInfo || {};

      if (approvalInfoParam.status == approvalInfoStatus.pending) {
        let approvalData = { 'approval_required': true } as any;

        if (safeApprovalInfo.reason) {
          approvalData['reason'] = safeApprovalInfo.reason;
        }

        return approvalData;
      } else {
        const newApprovalData = this.getApprovalInfoObj(approvalInfoParam, approvedPropertyName, isCharges, attributeName);
        return Object.assign({}, safeApprovalInfo, newApprovalData);
      }
    },
    getApprovalInfoObj(approvalInfoParam: any, approvedPropertyName: string, isCharges: boolean, attributeName: string): any {

      const lineFieldValue = approvalInfoParam.lineFieldValue ? approvalInfoParam.lineFieldValue : 0;
      const poFieldValue = approvalInfoParam.poFieldValue ? approvalInfoParam.poFieldValue : 0;

      let approvedValue = 0;
      let rejectedValue = 0;

      if (approvalInfoParam.status == approvalInfoStatus.approved) {
        approvedValue = lineFieldValue;
        rejectedValue = 0;
      }

      if (approvalInfoParam.status == approvalInfoStatus.rejected) {
        approvedValue = poFieldValue;

        if (attributeName && attributeName.toLowerCase().includes('date')) {
          rejectedValue = this.dateDifferenceInMiliSec(lineFieldValue, poFieldValue);
        } else {
          rejectedValue = lineFieldValue - poFieldValue;
        }
      }

      let approvalData: any = {
        'approval_required': true,
        'approval_status': approvalInfoParam.status,
        'approved_or_rejected_by': approvalInfoParam.currentUserId,
        'approved_or_rejected_at': approvalInfoParam.currentDateTime,
      }

      if (attributeName && attributeName.toLowerCase().includes('date')) {
        approvalData['approved_date'] = approvedValue;
        approvalData['rejected_date'] = rejectedValue;

      } else {
        approvalData['approved_amount'] = approvedValue;
        approvalData['rejected_amount'] = rejectedValue;
      }

      if (isCharges) {
        approvalData['approval_type'] = approvedPropertyName;
      }

      return approvalData;
    },
  },
  setup() {

    const po_match_store = usePoMatchStore();
    const { PODataObj, lineDataObj, PO_TABLE_MAP, PO_TABLE_MAP_REVERSE } = storeToRefs(po_match_store);
    const { buildPoLinesObj, prepareLinedictionary, prepareLineMapping } = po_match_store;

    const doc_store = useDocumentStore();
    const { checkTableApprovalpermission, getChargesNameByCostingElement, prepareChargesFields } = doc_store;
    const { record, tablePermissions, fieldPermissions } = storeToRefs(doc_store);

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);

    const master_data_lookup = useMasterDataLookupStore();
    const { prepareCostingElementDictionary } = master_data_lookup;
    const { costingElementDictionary } = storeToRefs(master_data_lookup);

    const auth_token_store = useAuthTokenStore();
    const { isAdmin } = auth_token_store;

    return {
      isAdmin,
      buildPoLinesObj,
      prepareChargesFields,
      prepareLinedictionary,
      prepareLineMapping,
      prepareCostingElementDictionary,
      getChargesNameByCostingElement,
      checkTableApprovalpermission,
      costingElementDictionary,
      user_settings,
      lineDataObj,
      PODataObj,
      record,
      tablePermissions,
      fieldPermissions,
      approvalNeededColumns: ref(new Set()),
      PO_TABLE_MAP,
      PO_TABLE_MAP_REVERSE,
    };
  },
});
</script>

