<template>
  <div class="q-pa-sm full-width">
    <q-tabs
      :narrow-indicator="false"
      active-class="highlighted-back"
      v-model="tab"
      class="text-weight-bold align-tabs-left"
      active-color="primary"
      indicator-color="primary"
    >
      <q-tab
        name="compare_line_items"
        :label="$t('compare_line_items')"
        v-if="display_tabs && showComparisonTable"
      />

      <q-tab
        name="invoice_line_items"
        :label="$t('invoice_line_items')"
        v-if="display_tabs"
      />

      <template v-if="isFormBuilderMode">
        <q-tab name="po_tables" :label="$t('po_tables')">
          <q-badge
            v-if="!doc_attributes[po_table_in_layout_builder]"
            color="amber"
            text-color="white"
            floating
          >
            <q-icon color="white" :name="'warning'">
              <q-tooltip>{{ $t('module_disabled') }}</q-tooltip>
            </q-icon>
          </q-badge>
        </q-tab>
      </template>
      <template v-else-if="doc_attributes[po_table_in_layout_builder]">
        <template v-if="!po_items_loaded">
          <span class="q-ml-sm alert-text">{{ $t('loading_po_tables') }}</span>
          <q-spinner-dots
            color="grey"
            size="2em"
            class="q-ml-sm"
          ></q-spinner-dots>
        </template>

        <q-tab
          name="po_tables"
          :label="$t('po_tables')"
          v-if="po_items_loaded && po_items.length === 0"
        >
          <q-tooltip>{{ $t('po_table_not_found') }}</q-tooltip>
        </q-tab>
        <template v-else-if="po_items_loaded && objLen(po_items) > 0">
          <q-tab
            v-for="(rows, index) in po_items"
            :key="index"
            :name="index"
            :data-name="index"
            tabindex="0"
            class="po-tab"
          >
            <div class="row full-width">
              <q-icon
                class="q-mr-sm mt-3 po-indication-icon"
                name="link_off"
              >
                <q-tooltip>{{ $t('po_table') }}</q-tooltip>
              </q-icon>
              <label>{{ index }}</label>
              <q-menu context-menu>
                <q-list>
                  <q-item
                    clickable
                    v-close-popup
                    @click="copyToClipboard(index)"
                  >
                    <q-item-section>
                      {{ $t('copy_to_clipboard') }}
                    </q-item-section>
                  </q-item>
                </q-list>
              </q-menu>
            </div>
          </q-tab>
        </template>
      </template>
    </q-tabs>

    <q-tab-panels v-model="tab" class="page-background">
      <q-tab-panel
        name="compare_line_items"
        v-if="display_tabs && showComparisonTable"
        class="no-padding"
      >
        <q-separator />
        <LineItemApprovalTable
          :isReadOnly="isReadOnly"
          :columnLblPrefix="currentField.columnLblPrefix"
        />
      </q-tab-panel>

      <q-tab-panel
        name="invoice_line_items"
        v-if="display_tabs"
        class="no-padding"
      >
        <div class="full-width" v-if="has_ai_table">
          <AIExtractedTable :isReadOnly="true" />
        </div>

        <div class="full-width" v-else-if="table_extration_setting">
          <LineItemTable
            :fieldName="firstTableName"
            v-if="renderTable"
            :isReadOnly="true"
          />
        </div>
      </q-tab-panel>

      <template
        v-if="
          doc_attributes[po_table_in_layout_builder] &&
          po_items_loaded &&
          objLen(po_items) > 0
        "
      >
        <!-- <POTabPanels /> -->
        <template v-for="(rows, index) in po_items" :key="index">
          <q-tab-panel :name="index" class="no-padding">
            <template v-if="loading_panels">
              <span class="q-ml-sm alert-text">{{
                $t('loading_po_tables')
              }}</span>
              <q-spinner-dots
                color="grey"
                size="2em"
                class="q-ml-sm"
              ></q-spinner-dots>
            </template>
            <template v-else>
              <template v-if="visible_columns && objLen(visible_columns) > 0">
                <PoTable
                  :po_lines="rows"
                  :po_number="String(index)"
                  :visible_columns="visible_columns"
                />
                <template
                  v-if="visible_columns && objLen(visible_columns) == 0"
                >
                  no po columns found
                </template>
              </template>
            </template>
          </q-tab-panel>
        </template>
      </template>
    </q-tab-panels>
  </div>

  <q-dialog v-model="delete_tab_confirmation" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('delete_po_tab') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
          @click="delete_tab_po_number = ''"
        />
        <f-btn
          data-cy="done"
          :label="$t('proceed')"
          v-close-popup
          @click="proceedDeletePoTab()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { objLen } from 'src/utils/general';
import documentUtil from 'src/utils/documentUtil';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { po_table_columns, CONSTANTS } from 'src/constants';
import { copyToClipboard as quasarCopyToClipboard } from 'quasar';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';
import LineItemTable from 'src/pages/TableExtraction/LineItemTable.vue';
import { FormBuilder } from 'src/formBuilder/form_elements/formbuilder.js';
import PoTable from 'src/components/formBuilder/PurchaseOrder/PoTable.vue';
import LineItemApprovalTable from 'src/pages/Settings/Components/Approval/LineItemApprovalTable.vue';
import {
  useFormBuilderStore,
  useDocumentStore,
  useSettingStore,
  useDocAttributesStore,
  usePoMatchStore,
} from 'src/store/main';
// No need to create the copy, old one will be used
import AIExtractedTable from 'src/formBuilder/form_elements/FormElementAIExtractedTable.vue';
import { notify } from 'src/components/notifications/notify';
import {
  table_extraction_setting,
  po_table_in_layout_builder,
  AI_table_extraction_setting,
} from 'src/constants';

let _this: any;

export default defineComponent({
  name: 'extracted-table-tab-panels',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['inputValueChanges', 'updateModel'],
  mixins: [displayFieldLabel, formBuilderHelper, documentUtil],
  components: {
    PoTable,
    LineItemTable,
    AIExtractedTable,
    LineItemApprovalTable,
    // POTabPanels,
    // IgnoreTableValidation,
  },
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.init();
      },
    },
    po_items_loaded: {
      handler: function (newVal, oldVal) {
        this.initPoTabPanels();
      },
    },
  },
  data() {
    return {
      tables: ref(FormBuilder.data().tables),
      renderTable: ref(false),
      firstTableName: ref(''),
      extractedTables: ref([] as any),
      table_extraction_setting,
      po_table_in_layout_builder,
      AI_table_extraction_setting,
      objLen,

      po_table_columns,
      showComparisonTable: ref(false),
    };
  },
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
      // this.fieldAddedByDesigner();
    }
  },
  mounted() {
    //  mout event listeners
    this.init();
    document.addEventListener('prepare_rows', this.reRenderPanel);
    (<any>window).fvt = this;
    _this = this;
  },
  unmounted: function () {
    //  unmout event listeners
    document.removeEventListener('prepare_rows', this.reRenderPanel);
  },
  methods: {
    init() {
      if (this.isFormBuilderMode) {
        this.AI_setting_flag = true;
        this.table_extration_setting = true;
        return;
      }

      this.isPoTableInLayoutBuilder();
      this.initPoTabPanels();

      if (this.record.table_blocked) {
        this.display_tabs = false;
        return;
      }

      // if this.record dont have tables then return
      if (!this.record.tables || Object.keys(this.record.tables).length === 0) {
        this.display_tabs = false;
        return;
      }

      if (this.record.status == CONSTANTS.validated_pending_approval || this.record.status == CONSTANTS.approved_pending_second_approval) {
        this.showComparisonTable = true;
        this.tab = 'compare_line_items';
      }

      this.display_tabs = true;
      this.prepareTables();

      this.checkSetting();
      this.handleTabChange();
    },
    async copyToClipboard(text: string | number) {
      try {
        if (!text) {
          return;
        }
        if (typeof text === 'number') {
          text = text.toString();
        }
        await quasarCopyToClipboard(text);
        notify.success(this.$t('success_copy_to_clipboard'));
      } catch (err) {
        notify.error(this.$t('error_copy_to_clipboard'));
      }
    },
    handleTabChange() {
      if (this.has_ai_table && this.AI_setting_flag) {
        this.tab = 'compare_line_items';
      }
    },

    checkSetting() {
      this.AI_setting_flag = false;
      this.table_extration_setting = false;
      if (this.user_settings[this.AI_table_extraction_setting]) {
        this.AI_setting_flag =
          this.user_settings[this.AI_table_extraction_setting];
      }

      if (this.user_settings[this.table_extraction_setting]) {
        this.table_extration_setting =
          this.user_settings[this.table_extraction_setting];
      }

      if (!this.AI_setting_flag && !this.table_extration_setting) {
        this.$nextTick(function () {
          setTimeout(function () {
            _this.isExtenedPanel = false;
            const event = new CustomEvent('set_splitter_model', {
              detail: { data: false },
            });
            document.dispatchEvent(event);
          }, 100);
        });
      }
    },

    async prepareTables() {
      // const docType = this.$route.params.doc_type as string;

      await this.getDocumentTables(this.docType);

      for (let [tbl_name, tbl] of Object.entries(this.documentTables)) {
        this.tables[0].name = tbl_name;
        this.tables[0].text = 'Table (' + tbl_name + ')';

        this.extractedTables.push(JSON.parse(JSON.stringify(this.tables[0])));

        this.documentTableNames.push(tbl_name);

        this.firstTableName = this.documentTableNames[0];
      }
      this.renderTable = true;
    },

    goToTableExtraction() {
      if (this.isFormBuilderMode) {
        return;
      }
      this.$router.push('/tbl_ext_v3/' + this.$route.params.id);
    },

    reRenderPanel() {
      this.init();
    },

    async initPoTabPanels() {
      try {
        if (
          this.isFormBuilderMode ||
          this.po_items_loaded === false ||
          this.objLen(this.po_items) == 0 ||
          this.doc_attributes[this.po_table_in_layout_builder] === false ||
          this.objLen(this.visible_columns) > 0
        ) {
          return;
        }

        this.loading_panels = true;
        await this.getPOColumns();
        await this.startSettingsFetch();

        this.visible_columns = await this.getSavedColumns(
          this.po_table_columns,
        );
      } catch (error) {
        logError('Error in initPoTabPanels', error);
      } finally {
        this.loading_panels = false;
      }
    },

    proceedDeletePoTab() {
      this.handleTabChange();
      this.deletePoTab();
      // custom event to save document
      // const event = new CustomEvent('save_document', { detail: { data: true } });
      // document.dispatchEvent(event);
    },
    // if ai table does not have data then show extracted table
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      formBuilderConfigModel,
      isFormBuilderMode,
      documentTableNames,
      documentTables,
      isExtenedPanel,
      docType,
    } = storeToRefs(form_builder_store);

    const { getDocumentTables } = form_builder_store;

    const doc_store = useDocumentStore();
    const {
      doc_loaded,
      selected_doc_type,
      has_ai_table,
      record,
      po_items,
      po_items_loaded,
      delete_tab_confirmation,
      delete_tab_po_number,
    } = storeToRefs(doc_store);
    const {
      isPoTableInLayoutBuilder,
      isPODeleteAble,
      proceedToClosePOTab,
      refreshPOItems,
      deletePoTab,
    } = doc_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { startSettingsFetch } = settings_store;

    const doc_attribute_store = useDocAttributesStore();
    const { model: doc_attributes } = storeToRefs(doc_attribute_store);

    const po_match_store = usePoMatchStore();
    const { table_columns } = storeToRefs(po_match_store);
    const { getSavedColumns, getPOColumns } = po_match_store;

    return {
      delete_tab_confirmation,
      deletePoTab,
      delete_tab_po_number,
      refreshPOItems,
      proceedToClosePOTab,
      isPODeleteAble,
      getPOColumns,
      startSettingsFetch,
      loading_panels: ref(false),
      table_columns,
      getSavedColumns,
      isPoTableInLayoutBuilder,
      po_items,
      po_items_loaded,
      selected_doc_type,
      doc_attributes,
      user_settings,
      record,
      docType,
      doc_loaded,
      has_ai_table,
      documentTables,
      isExtenedPanel,
      formBuilderModel,
      isFormBuilderMode,
      documentTableNames,
      formBuilderConfigModel,
      tab: ref('invoice_line_items'),
      quasarCopyToClipboard,
      AI_setting_flag: ref(false),
      table_extration_setting: ref(false),
      display_tabs: ref(true),
      visible_columns: ref([] as any),

      //functions
      getDocumentTables,
    };
  },
});
</script>
